import React, { useEffect, useState } from "react";
import { useParams, useNavigate, useLocation } from "react-router-dom";
import axios from "axios";
import { ToastContainer, toast } from 'react-toastify';
import 'react-toastify/dist/ReactToastify.css';

const ListarPagosCobrosDetallados = () => {
  const { userId } = useParams();
  const location = useLocation();
  const queryParams = new URLSearchParams(location.search);
  const mes = queryParams.get('mes');
  const navigate = useNavigate();
  
  const [detalles, setDetalles] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [usuario, setUsuario] = useState(null);
  
  // Estados para los modales
  const [showModal, setShowModal] = useState(false);
  const [modalType, setModalType] = useState(null); // 'bonificar' o 'sancionar'
  const [currentCobroId, setCurrentCobroId] = useState(null);
  
  // Estados para los formularios
  const [formData, setFormData] = useState({
    monto: '',
    nota: ''
  });

  useEffect(() => {
    const fetchDetalles = async () => {
      try {
        setLoading(true);
        const token = localStorage.getItem("auth");
        
        // Obtener detalles del usuario
        const userResponse = await axios.get(`https://sistemacontable-wico.onrender.com/api/usuario/${userId}/`, {
          headers: { Authorization: `Bearer ${token}` }
        });
        setUsuario(userResponse.data);
        
        // Obtener TODOS los cobros primero
        const cobrosResponse = await axios.get(`https://sistemacontable-wico.onrender.com/api/listar_cobro/`, {
          headers: { Authorization: `Bearer ${token}` }
        });
        
        // Filtrar los cobros para el usuario y mes específicos
        const cobrosFiltrados = cobrosResponse.data.filter(cobro => {
          const coincideUsuario = cobro.usuario_registra?.id === parseInt(userId);
          const coincideMes = mes ? cobro.mes?.toLowerCase() === mes.toLowerCase() : true;
          return coincideUsuario && coincideMes;
        });
        
        setDetalles(cobrosFiltrados);
      } catch (error) {
        console.error("Error al obtener detalles", error);
        setError(error.message);
      } finally {
        setLoading(false);
      }
    };

    fetchDetalles();
  }, [userId, mes]);

  const handleVerDetalles = (cobroId) => {
    navigate(`/gestPago/listarRegistrosDeCobros/${cobroId}`);
  };

  // Manejadores para los modales
  const handleOpenModal = (type, cobroId) => {
    setModalType(type);
    setCurrentCobroId(cobroId);
    setShowModal(true);
    setFormData({ monto: '', nota: '' }); // Resetear formulario
  };

  const handleCloseModal = () => {
    setShowModal(false);
    setModalType(null);
    setCurrentCobroId(null);
  };

  // Manejador para cambios en el formulario
  const handleFormChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: value
    }));
  };

  // Enviar bonificación o sanción
  const handleSubmit = async () => {
    try {
      const token = localStorage.getItem("auth");
      const payload = {};
      
      if (modalType === 'bonificar') {
        payload.bonificado = parseFloat(formData.monto);
        payload.nota_bonificado = formData.nota;
      } else {
        payload.sancionado = parseFloat(formData.monto);
        payload.nota_sancionado = formData.nota;
      }
      
      await axios.put(
        `https://sistemacontable-wico.onrender.com/api/sancionar_acreditar/${currentCobroId}/`,
        payload,
        {
          headers: { 
            'Authorization': `Bearer ${token}`,
            'Content-Type': 'application/json'
          }
        }
      );
      
      toast.success(`${modalType === 'bonificar' ? 'Bonificación' : 'Sanción'} aplicada correctamente`);
      handleCloseModal();
      
      // Actualizar la lista de cobros
      const response = await axios.get(`https://sistemacontable-wico.onrender.com/api/listar_cobro/`, {
        headers: { Authorization: `Bearer ${token}` }
      });
      setDetalles(response.data.filter(cobro => {
        const coincideUsuario = cobro.usuario_registra?.id === parseInt(userId);
        const coincideMes = mes ? cobro.mes?.toLowerCase() === mes.toLowerCase() : true;
        return coincideUsuario && coincideMes;
      }));
      
    } catch (error) {
      console.error(`Error al aplicar ${modalType}`, error);
      toast.error(error.response?.data?.message || `Error al aplicar ${modalType}`);
    }
  };

  if (loading) return <div>Cargando detalles...</div>;
  if (error) return <div className="alert alert-danger">Error: {error}</div>;

  return (
    <div className="container mt-4">
      <ToastContainer position="top-right" autoClose={3000} />
      
      <div className="d-flex justify-content-between align-items-center mb-4">
        <h2>Detalles de cobros para {usuario?.first_name} {usuario?.last_name}</h2>
        <button 
          onClick={() => navigate(-1)} 
          className="btn btn-secondary"
        >
          Volver
        </button>
      </div>
      
      <h5 className="mb-3">Mes: {mes || 'Todos'}</h5>
      
      <div className="card mb-4 shadow-sm">
        <div className="card-header bg-dark text-white">
          <h3 className="m-0">Detalles de Cobros</h3>
        </div>
        <div className="card-body">
          <div className="table-responsive" style={{ maxHeight: '400px', overflowY: 'auto' }}>
            <table className="table table-striped table-hover">
              <thead className="table-dark" style={{ position: 'sticky', top: 0 }}>
                <tr>
                  <th>ID Cobro</th>
                  <th>Cliente</th>
                  <th>Documento</th>
                  <th>Unidades</th>
                  <th>Tipo</th>
                  <th>Fecha</th>
                  <th>Acciones</th>
                </tr>
              </thead>
              <tbody>
                {detalles.length > 0 ? (
                  detalles.map((cobro) => (
                    <tr key={cobro.id}>
                      <td>{cobro.id}</td>
                      <td>{cobro.cliente?.nombre || 'N/A'}</td>
                      <td>{cobro.documento?.nombre_documento || 'N/A'}</td>
                      <td>
                        {cobro.contenido?.reduce((sum, item) => sum + (item.unidades || 0), 0) ||
                         cobro.contenido_open?.reduce((sum, item) => sum + (item.unidades || 0), 0) ||
                         cobro.contenido_spr?.reduce((sum, item) => sum + (item.unidades || 0), 0) ||
                         cobro.unidades || 0}
                      </td>
                      <td>
                        {cobro.tipo_tarea === 1 && 'Bill'}
                        {cobro.tipo_tarea === 2 && 'Subir Notas al Sistema'}
                        {cobro.tipo_tarea === 3 && 'Realizar Billes'}
                        {cobro.tipo_tarea === 4 && 'Open'}
                        {cobro.tipo_tarea === 5 && 'SPR'}
                      </td>
                      <td>{cobro.mes || 'N/A'}</td>
                      <td>
                        <div className="d-flex gap-2">
                          <button 
                            onClick={() => handleVerDetalles(cobro.id)}
                            className="btn btn-sm btn-primary"
                          >
                            Detalles
                          </button>
                          <button 
                            onClick={() => handleOpenModal('bonificar', cobro.id)}
                            className="btn btn-sm btn-success"
                          >
                            Bonificar
                          </button>
                          <button 
                            onClick={() => handleOpenModal('sancionar', cobro.id)}
                            className="btn btn-sm btn-warning"
                          >
                            Sancionar
                          </button>
                        </div>
                      </td>
                    </tr>
                  ))
                ) : (
                  <tr>
                    <td colSpan="7" className="text-center">
                      No se encontraron cobros para este usuario{mes ? ` en el mes de ${mes}` : ''}
                    </td>
                  </tr>
                )}
              </tbody>
            </table>
          </div>
        </div>
      </div>

      {/* Modal dinámico para Bonificar/Sancionar */}
      <div className={`modal fade ${showModal ? 'show d-block' : ''}`} tabIndex="-1" style={{ backgroundColor: 'rgba(0,0,0,0.5)' }}>
        <div className="modal-dialog">
          <div className="modal-content">
            <div className={`modal-header ${modalType === 'bonificar' ? 'bg-success' : 'bg-warning'} text-white`}>
              <h5 className="modal-title">{modalType === 'bonificar' ? 'Bonificar Cobro' : 'Sancionar Cobro'}</h5>
              <button type="button" className="btn-close" onClick={handleCloseModal}></button>
            </div>
            <div className="modal-body">
              <div className="mb-3">
                <label className="form-label">Monto</label>
                <input
                  type="number"
                  className="form-control"
                  name="monto"
                  value={formData.monto}
                  onChange={handleFormChange}
                  placeholder={`Ej: ${modalType === 'bonificar' ? '33' : '22'}`}
                />
              </div>
              <div className="mb-3">
                <label className="form-label">Motivo</label>
                <textarea
                  className="form-control"
                  name="nota"
                  value={formData.nota}
                  onChange={handleFormChange}
                  placeholder={`Ej: ${modalType === 'bonificar' ? 'Por sobresaliente' : 'Por incumplimiento'}`}
                  rows="3"
                ></textarea>
              </div>
            </div>
            <div className="modal-footer">
              <button type="button" className="btn btn-secondary" onClick={handleCloseModal}>
                Cancelar
              </button>
              <button 
                type="button" 
                className={`btn ${modalType === 'bonificar' ? 'btn-success' : 'btn-warning'}`} 
                onClick={handleSubmit}
              >
                {modalType === 'bonificar' ? 'Aplicar Bonificación' : 'Aplicar Sanción'}
              </button>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default ListarPagosCobrosDetallados;